import zipfile
from lxml import etree

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

with zipfile.ZipFile('/work/complaint_preparation.docx', 'r') as z:
    styles_xml = etree.fromstring(z.read('word/styles.xml'))
    doc_xml = etree.fromstring(z.read('word/document.xml'))

print('=== Checking styles.xml ===')
for style in styles_xml.findall('w:style', ns):
    style_id = style.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}styleId')
    name_el = style.find('w:name', ns)
    name = name_el.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val') if name_el is not None else ''
    rPr = style.find('w:rPr', ns)
    if rPr is not None:
        rFonts = rPr.find('w:rFonts', ns)
        if rFonts is not None:
            attrs = {k.split('}')[-1]: v for k, v in rFonts.attrib.items()}
            print(f'Style {style_id} ({name}): {attrs}')
        else:
            print(f'Style {style_id} ({name}): NO rFonts')

print('\n=== Checking document.xml paragraphs and runs ===')
body = doc_xml.find('w:body', ns)
all_ok = True
for idx, p in enumerate(body.findall('.//w:p', ns)):
    pStyle = p.find('w:pPr/w:pStyle', ns)
    style_val = pStyle.get('{http://schemas.openxmlformats.org/wordprocessingml/2006/main}val') if pStyle is not None else 'Normal'
    runs = p.findall('w:r', ns)
    text = ''.join(p.itertext()).strip()
    if not runs:
        continue
    for r in runs:
        rFonts = r.find('w:rPr/w:rFonts', ns)
        if rFonts is None:
            print(f'ERROR: Para {idx} ({style_val}) run missing rFonts: {text[:30]}')
            all_ok = False
        else:
            attrs = {k.split('}')[-1]: v for k, v in rFonts.attrib.items()}
            expected = 'SimHei' if style_val in ('Title', 'Subtitle', 'Heading1', 'Heading2', 'Heading3') else 'FangSong'
            for k in ('ascii', 'hAnsi', 'eastAsia', 'cs'):
                if attrs.get(k) != expected:
                    print(f'ERROR: Para {idx} ({style_val}) attr {k}={attrs.get(k)} != {expected}: {text[:30]}')
                    all_ok = False
    if style_val in ('Title', 'Subtitle', 'Heading1', 'Heading2', 'Heading3'):
        print(f'HEADING [{style_val}]: {text}')

print('\nAll runs & headings verified OK:', all_ok)
"

