import zipfile
from lxml import etree

ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with zipfile.ZipFile('/work/complaint_preparation.docx', 'r') as z:
    styles_xml = etree.fromstring(z.read('word/styles.xml'))
    doc_xml = etree.fromstring(z.read('word/document.xml'))

missing_styles = 0
for style in styles_xml.findall('w:style', ns):
    rPr = style.find('w:rPr', ns)
    if rPr is None or rPr.find('w:rFonts', ns) is None:
        missing_styles += 1

all_runs = doc_xml.findall('.//w:r', ns)
bad_runs = 0
for r in all_runs:
    rf = r.find('w:rPr/w:rFonts', ns)
    if rf is None:
        bad_runs += 1
    else:
        attrs = {k.split('}')[-1]: v for k, v in rf.attrib.items()}
        vals = {attrs.get('ascii'), attrs.get('hAnsi'), attrs.get('eastAsia'), attrs.get('cs')}
        if vals not in ({'SimHei'}, {'FangSong'}):
            bad_runs += 1

print(f'Total styles missing rFonts: {missing_styles}')
print(f'Total runs in document.xml: {len(all_runs)}, bad runs: {bad_runs}')
"
